 if(!loan){dialog('学びの貸与',`<h2>返すことも含めて、選ぶ。</h2><p>受け取ったお金は手持ちに入ります。貸与を終えた後に返済が始まります。</p><div class="story-choices">${Object.keys(Finance.EDUCATION_LOAN_OFFERS).map(id=>{const q=Finance.quoteEducationLoan(state,id);return btn(`<strong>${id==='interestFree'?'無利子の貸与':'利息のある貸与'}</strong><span>月 ${yen(q.monthly)} · 最大 ${q.maxMonths}か月${q.reason?' · '+esc(q.reason):''}</span>`,'education-quote',`data-id="${id}" ${q.available?'':'disabled'}`,'choice');}).join('')}</div>`);return;}
 const status={lending:'貸与中',waiting:'返済開始を待っている',repaying:'返済中',settled:'返済完了'}[loan.status];dialog('学びの貸与',`<h2>${status}</h2><div class="money-lines"><span>受け取った合計 <b>${yen(loan.paidOut)}</b></span><span>残元金 <b>${yen(loan.principal)}</b></span><span>利息・延滞費 <b>${yen(loan.interest+loan.lateFees)}</b></span><span>未払い <b>${yen(loan.totalOverdue)}</b></span><span>これまでの返済 <b>${yen(loan.paid)}</b></span>${loan.nextDueMonth!==null?`<span>次の返済 <b>${loanMonth(loan.nextDueMonth)}</b></span>`:''}</div>${loan.status==='lending'?`<p>月 ${yen(loan.monthly)}。休学・卒業・停止、または上限に達すると貸与が終わります。</p>${btn('貸与を停止する','education-stop-confirm','','button subtle')}`:['waiting','repaying'].includes(loan.status)?`<p>返済は毎月。猶予中も残高は消えません。</p><label>任意の返済額<input id="education-repay-amount" type="number" min="1" step="1000" inputmode="numeric" value="${Math.min(state.cash,loan.balance)}"></label><p id="education-feedback" class="notice" role="status" hidden></p><div class="button-row">${btn('返済額を確認','education-repay-preview','','button subtle')}${btn('返済の猶予を相談','education-relief','','button subtle')}</div><p class="tiny">手持ちが3万円以下のとき、翌月から3か月の猶予を相談できます。</p>`:'<p>貸与の残高はありません。</p>'}${btn('資金の画面へ戻る','finance','','text-button')}`,true);
