function educationQuote(id){const q=Finance.quoteEducationLoan(state,id);if(!q.available)throw Error(q.reason);dialog('貸与の確認',`<h2>${id==='interestFree'?'無利子の貸与':'利息のある貸与'}</h2><div class="money-lines"><span>毎月の貸与 <b>${yen(q.monthly)}</b></span><span>最大期間 <b>${q.maxMonths}か月</b></span><span>年利 <b>${q.annualRate*100}%</b></span><span>最初の入金 <b>${loanMonth(q.firstDepositMonth)}</b></span><span>返済開始 <b>貸与終了の7か月後</b></span><span>返済回数 <b>最大${q.repaymentMonths}回</b></span></div><p>満額を受け取った場合、初回の返済例 ${yen(q.exampleFirstPayment)}、総返済例 ${yen(q.exampleTotalPayment)}。延滞時は前月からの未払い元金に月0.25%の延滞費がかかります。</p><p>手持ちが3万円以下のときは、3か月単位で返済の猶予を相談できます。猶予しても残高はなくなりません。</p><div class="dialog-actions">${btn('戻る','education','','button subtle')}${btn('貸与を申し込む','education-start',`data-id="${esc(id)}"`,'button primary')}</div>`,true);}
function sources(){dialog('遊び方と出典',`<h2>この一年を、どう過ごそう。</h2><ol><li>週間方針を選んで一週間を進める。仕事と運動の量は選択できる。</li><li>学習室では単元と教材を選ぶ。忘れかけたところへ戻り、白紙から思い出す。</li><li>過去問は、初見の演習・答案分析・日を置いた解き直し。</li><li>大学の単位、財布、体、友人との時間にも気を配る。</li><li>私立は12月末、国公立は共通テスト後の1月末に出願。個別試験まで対策を続ける。</li></ol><h3>入試の資料</h3><p>82機関の名称と河合塾の代表方式の難度帯を確認。個別の大学公式資料を確認した学校には、その範囲を資料室に記載しています。</p><div class="source-list">${RESEARCH_SOURCES.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a>`).join('')}</div><h3>暮らしと学習</h3><div class="source-list"><a href="https://www.rekibun.or.jp/grutto/facilities/" target="_blank" rel="noopener noreferrer">東京・ミュージアム ぐるっとパス2026 対象施設 ↗</a><a href="https://www.jaza.jp/search-enkan" target="_blank" rel="noopener noreferrer">日本動物園水族館協会 施設一覧 ↗</a><a href="https://www.obunsha.co.jp/product/series/c002" target="_blank" rel="noopener noreferrer">旺文社 参考書と定価 ↗</a><a href="https://www.sej.co.jp/products/" target="_blank" rel="noopener noreferrer">セブン‐イレブン 商品情報 ↗</a><a href="https://www.niddk.nih.gov/health-information/diabetes/overview/risk-factors-type-2-diabetes" target="_blank" rel="noopener noreferrer">NIDDK：2型糖尿病の複合的なリスク要因 ↗</a><a href="https://www.pnas.org/doi/10.1073/pnas.2413511121" target="_blank" rel="noopener noreferrer">思い出す練習と学習についての研究 ↗</a></div><h3>キャラクター</h3><p>ポロを。／zanobapitch。指定された3パックのスタンプを使用しています。</p><div class="source-list">${['32805644','32825071','32986541'].map((id,i)=>`<a href="https://store.line.me/stickershop/product/${id}/ja" target="_blank" rel="noopener noreferrer">LINEスタンプ ${i+1} ↗</a>`).join('')}</div><p class="tiny">資料の調査日：2026年9月22日。地域枠・推薦・編入・生物選択・補欠繰上げは掲載していません。商品の税込定価・参考価格と、予算目安を区別しています。</p>`,true);}
function settings(){dialog('この端末の設定',`<h2>一年の記録を、手元に。</h2><p>データはこのブラウザに自動保存されます。端末やブラウザが変わると共有されません。</p><p id="storage-status" role="status" aria-live="polite">${statusText()}</p><div class="story-choices">${btn('<strong>セーブデータを書き出す</strong><span>JSONファイルとして保存</span>','export','','choice')}<label class="choice"><strong>セーブデータを読み込む</strong><input id="import-save" type="file" accept="application/json,.json"></label>${btn('<strong>最初から始める</strong><span>現在の保存を置き換えます。確認画面へ。</span>','reset-confirm','','choice')}</div><p id="import-feedback" class="notice" role="status" aria-live="polite" hidden></p><p class="tiny">ゲーム版 ${E.VERSION}</p>`);}
const panes={week:'plan',study:'subjects',university:'campus',life:'outing',records:'journal'};
const pages={shop:0,venues:0,schools:0};let resetScroll=false;
function paneNav(group,options){return `<nav class="pane-nav" aria-label="${{week:'今週',study:'学習',university:'大学と仕事',life:'休日',records:'記録'}[group]}の切り替え">${options.map(([id,n])=>btn(n,'pane',`data-group="${group}" data-id="${id}" aria-pressed="${panes[group]===id}"`,'pane-button '+(panes[group]===id?'selected':''))).join('')}</nav>`;}
function slicePage(items,key,size){pages[key]=Math.min(pages[key],Math.max(0,Math.ceil(items.length/size)-1));return items.slice(pages[key]*size,(pages[key]+1)*size);}
function pager(key,total,size){const n=Math.max(1,Math.ceil(total/size));return `<div class="pager">${btn('前へ','page',`data-id="${key}" data-dir="-1" ${pages[key]===0?'disabled':''}`,'button subtle small')}<span>${pages[key]+1} / ${n} ページ · ${total}件</span>${btn('次へ','page',`data-id="${key}" data-dir="1" ${pages[key]>=n-1?'disabled':''}`,'button subtle small')}</div>`;}
function fragment(html,start){const pos=html.indexOf(start);if(pos<0)return '';const tag=html.slice(pos).match(/^<(\w+)/)[1],re=new RegExp('<\\/?'+tag+'\\b[^>]*>','g');re.lastIndex=pos;let depth=0,m;while((m=re.exec(html))){depth+=m[0].startsWith('</')?-1:1;if(!depth)return html.slice(pos,re.lastIndex);}return '';}
let pendingWeekPreferences=null;
function applyWeekPreferences(next){
 const baseline=P.automaticPlan(state,{},plan.methods),candidate=P.automaticPlan(state,next,plan.methods),free=new Set(freePositions());
 const scheduledCounts=p=>Object.fromEntries(D.ACTIVITIES.map(a=>[a.id,Object.entries(p.schedule||{}).filter(([i,id])=>free.has(+i)&&id===a.id).length]));
 const before=scheduledCounts(baseline),after=scheduledCounts(candidate);
 const lost=D.ACTIVITIES.filter(a=>plan.counts[a.id]!==before[a.id]&&plan.counts[a.id]!==after[a.id]);
 if(lost.length){pendingWeekPreferences={next,candidate};dialog('予定を組み直す',`<h2>手動で調整した予定が変わります</h2><p>${lost.map(a=>esc(a.name)).join('・')}の時間を含め、方針に合わせて組み直します。</p><div class="dialog-actions">${btn('今の予定に戻る','week-preferences-cancel','','button subtle')}${btn('組み直す','week-preferences-confirm','','button primary')}</div>`);return;}
 commitWeekPreferences(next,candidate);
}
function commitWeekPreferences(next,candidate){pendingWeekPreferences=null;state.weekly={...P.preferences(state),...next};plan=candidate;slots={...candidate.schedule};save();render();}
function aspirationCard(){
 const view=A.aspirationView(state);
 if(!view)return `<section class="panel aspiration-card"><p class="eyebrow">志望校</p><h2>行きたい場所を、考えてみる。</h2><p>出願前でも一校を選べます。後から変更でき、出願は別に行います。</p>${btn('受験資料室を見る '+icon('arrow',14),'nav','data-tab="schools"','button subtle')}</section>`;
 return `<section class="panel aspiration-card"><p class="eyebrow">志望校</p><h2>${esc(view.name)}</h2>${view.eligibility?`<p class="notice">出願資格：${esc(view.eligibility)}</p>`:''}<p>個別試験で重視する科目：${view.subjects.map(x=>esc(x.name)).join('・')}</p><p class="tiny">${esc(view.profileName)}の演習 ${view.profileBlocks*3}時間。学校固有の演習ではなく、同じ形式の累計です。実際の科目は大学の募集要項をご確認ください。</p>${btn('この学校を見る '+icon('arrow',14),'school',`data-id="${esc(view.id)}"`,'text-button')}</section>`;
}
function goalCard(){
 const active=state.goals?.active,def=G.GOALS.find(g=>g.id===active?.id),progress=G.goalProgress(state);
 const latest=state.goals?.history?.at(-1),lastDef=G.GOALS.find(g=>g.id===latest?.id);
 if(def&&progress)return `<section class="panel goal-card"><div class="goal-heading"><div><p class="eyebrow">小さな目標</p><h2>${esc(def.name)}</h2><p>残り${progress.weeksRemaining}週間 · ${esc(def.description)}</p></div><strong>${progress.value} <small>/ ${progress.target}${esc(progress.unit)}</small></strong></div><div class="goal-meter" role="progressbar" aria-label="目標の進み具合" aria-valuemin="0" aria-valuemax="${progress.target}" aria-valuenow="${progress.value}"><i style="width:${Math.min(100,100*progress.value/progress.target)}%"></i></div><p class="tiny">過ごした週だけを数えます。</p>${btn('目標を解除する','goal-cancel-confirm','','text-button')}</section>`;
 return `<section class="panel goal-card"><p class="eyebrow">小さな目標</p><h2>次の数週間に、ひとつ。</h2><p>勉強、運動、誰かと過ごす時間。自分で決めたことを、日々の記録に残せます。</p>${latest&&lastDef?`<p class="goal-last">前回：${esc(lastDef.name)} · ${{completed:'達成',expired:'期間終了',cancelled:'途中で解除'}[latest.status]||'記録'}（${latest.value} / ${latest.target}${esc(lastDef.unit)}）</p>`:''}${btn('目標を選ぶ '+icon('arrow',14),'goal-choose','','button subtle')}</section>`;
}
function goalChooser(){const weeks=Math.min(4,48-state.week);dialog('小さな目標',`<h2>次の${weeks}週間、何を大切にする？</h2><p>過ごした週の行動を記録します。1コマは3時間。目標はいつでも解除できます。</p><div class="story-choices">${G.GOALS.map(g=>btn(`<strong>${esc(g.name)}</strong><span>${esc(g.description)} · ${Math.ceil(g.target*weeks/4)}${esc(g.unit)}</span>`,'goal-select',`data-id="${g.id}"`,'choice')).join('')}</div>`);}
function hobbyJournal(){const rows=(state.hobbyMilestones?.records||[]).slice().reverse();return `<details class="panel goal-journal"><summary>好きなことの節目</summary>${rows.length?rows.map(r=>{const entry=HM.HOBBY_MILESTONES[r.id]?.[r.stage],mode=HM.MILESTONE_MODES[r.mode];return entry&&mode?`<p><b>${esc(entry[0])}</b> · ${esc(mode.name)}<br><small>${E.calendar(r.week,r.year).year}年 ${E.calendar(r.week,r.year).label}</small></p>`:''}).join(''):'<p>まだ節目の記録はありません。</p>'}</details>`;}
