 if(a==='household-choice'){state=HH.chooseHousehold(state,+el.dataset.index);reconcileCurrentPlan();releaseHousing();close();save();render();if(state.pending)pending();return;}
 if(a==='narrative-next'){state=E.dismissNarrative(state);releaseHousing();close();save();render();if(state.pending)pending();return;}
 if(a==='hangout-choice'){state=E.resolveHangout(state,+el.dataset.index);reconcileCurrentPlan();releaseHousing();close();save();render();if(state.pending)pending();return;}
 if(a==='social-answer'){state=E.answerMessage(state,id,el.dataset.mode);save();render();return;}
 if(a==='trip-memory'){const t=state.social.trips.find(t=>t.key===id);if(t)dialog(t.title,`<h2>${esc(t.place)}</h2>${conversationLines(t.transcript)}`,true);return;}
 if(a==='outing-mode'){state=E.configureLife(state,'meetup',{...state.lifestyle.meetup,mode:id});for(const k of Object.keys(slots))if(['outing','meetup'].includes(slots[k]))delete slots[k];syncPlan();save();render();return;}
 if(a==='plan-outing'||a==='plan-group'){if(a==='plan-group')state=E.configureLife(state,'meetup',{...state.lifestyle.meetup,mode:'group'});place(state.lifestyle.meetup.mode==='group'?'meetup':'outing');toast('休日を予定しました。');return;}
 if(a==='more-menu'){dialog('どこへ行く？',`<div class="mobile-menu-grid">${navs.map(([id,name])=>btn(icon(id)+name,'nav',`data-tab="${id}"`,'button subtle')).join('')}</div>`);return;}
 if(a==='week-preferences-cancel'){pendingWeekPreferences=null;close();return;}if(a==='week-preferences-confirm'){const next=pendingWeekPreferences;if(next){close();commitWeekPreferences(next.next,next.candidate);}return;}
 if(a==='week-style'){applyWeekPreferences({style:id});return;}
 if(a==='plan-less'){if(plan.counts[id])plan.counts[id]=['outing','meetup'].includes(id)?0:plan.counts[id]-1;restoreSlots(plan);save();render();return;}
 if(a==='start'){state=E.newGame(undefined,{family:$('start-family').value,home:+$('start-home').value,womenEligible:$('start-women').checked});resetPlan();save();render();return;}
 if(a==='close'){close();return;}if(a==='nav'){e.preventDefault();close();tab=el.dataset.tab;resetScroll=true;render();window.scrollTo(0,0);return;}
 if(a==='shift-answer'){state=E.answerShift(state,id);save();render();toast('塾へ返事をしました。');return;}
 if(a==='market-form'){marketOrderForm(id,el.dataset.side);return;}
 if(a==='market-preview'){try{marketPreview(id,el.dataset.side,el.dataset.kind);}catch(error){const f=$('market-feedback');if(f){f.hidden=false;f.textContent=error.message;}}return;}
 if(a==='market-confirm'){try{const o=pendingMarketOrder;if(!o)throw Error('もう一度注文を確認してください。');if(o.kind==='market'&&Market.tradeQuote(state,o.id,o.side).price!==o.price)throw Error('価格が変わりました。もう一度確認してください。');state=o.kind==='market'?E.trade(state,o.id,o.side):Market.placeLimitOrder(state,o.id,o.side,o.limit);pendingMarketOrder=null;close();save();render();marketDialog();}catch(error){const f=$('market-feedback');if(f){f.hidden=false;f.textContent=error.message;}}return;}
