function change(e){const t=e.target,id=t.id;if(id==='recovery-import'){recoverFile(t);return;}if(storageBusy)return;try{if(!state)return;
 if(['shop-query','school-query','venue-query'].includes(id)){if(id==='shop-query'){shopQuery=t.value;shopLimit=36;pages.shop=0;}else if(id==='school-query'){schoolQuery=t.value;pages.schools=0;}else{venueQuery=t.value;venueLimit=12;pages.venues=0;}return;}
 if(id==='study-pick'){studySubject=t.value;render();return;}
 if(id==='desk-book'){if(t.value)state=E.equipBook(state,t.value);else {if(state.pending)throw Error('先に出来事を確認しよう。');delete state.lifestyle.books[studySubject];}save();render();return;}
 if(id==='book-approach'){const b=E.equippedBook(state,studySubject);if(b)state=E.setBookApproach(state,b.id,t.value);save();render();return;}
 if(id==='shop-category'){shopCat=t.value;if(!['すべて','参考書','持ちもの'].includes(shopCat))shopSubject='all';pages.shop=0;render();return;}
 if(id==='shop-subject'){shopSubject=t.value;pages.shop=0;render();return;}if(id==='shop-owned'){shopOwnedOnly=t.checked;pages.shop=0;render();return;}
 if(id==='meetup-game'){state=E.configureLife(state,'meetup',{...state.lifestyle.meetup,game:t.value});save();render();return;}
 if(['shop-query','shop-sort','shop-budget'].includes(id))pages.shop=0;
 if(['venue-query','venue-category','outing-pref','outing-kind'].includes(id))pages.venues=0;
 if(['school-query','school-region','school-type'].includes(id))pages.schools=0;
 if(id.startsWith('week-')){const key=id.slice(5),value=key==='pace'?t.value:+t.value;t.value=String(P.preferences(state)[key]);applyWeekPreferences({[key]:value});return;}
 if(id.startsWith('focus-')){state=E.setStudyFocus(state,id.slice(6),t.value);save();render();return;}
 if(id==='social-track'){state=E.setSocialTrack(state,t.value);save();render();return;}
 if(id==='shop-sort'){shopSort=t.value;shopLimit=36;render();return;}
 if(id==='shop-budget'){shopBudget=t.value;shopLimit=36;render();return;}
 if(id.startsWith('world-')){state=E.configureWorld(state,id.slice(6),t.value);save();render();return;}
 if(id==='review-mode'||id==='review-subject'){state=E.setReview(state,$('review-mode').value,$('review-subject').value);save();render();return;}
 if(id.startsWith('method-')){plan.methods[id.slice(7)]=t.value;save();return;}
 if(t.dataset.course){const enrolled=[...state.university.current.enrolled];if(t.checked)enrolled.push(t.dataset.course);else enrolled.splice(enrolled.indexOf(t.dataset.course),1);state=E.changeUniversity(state,{enrolled});reconcileCurrentPlan();}
 else if(id==='uni-policy'){state=E.changeUniversity(state,{policy:t.value});reconcileCurrentPlan();}else if(id==='uni-focus')state=E.changeUniversity(state,{focus:t.value});else if(id==='uni-exam'){state=E.changeUniversity(state,{examPolicy:t.value});reconcileCurrentPlan();}
 else if(id==='work-contract')state=E.setContract(state,t.value);
 else if(id.startsWith('secret-')){const allocation=[...state.lifestyle.secret.allocation];allocation[+id.slice(7)]=t.value;state=E.configureLife(state,'secret',{...state.lifestyle.secret,allocation});}
 else if(id==='venue-category'){venueCategory=t.value;venueLimit=12;}
 else if(id==='outing-pref'||id==='outing-kind'){venueLimit=12;venueQuery='';state=E.configureLife(state,'outing',{pref:+$('outing-pref').value,kind:$('outing-kind').value});for(const k of Object.keys(slots))if(['outing','meetup'].includes(slots[k]))delete slots[k];}
 else if(id==='meetup-topic')state=E.configureLife(state,'meetup',{...state.lifestyle.meetup,topic:t.value});
 else if(id==='pachinko-budget'){state.market.pachinkoBudget=Number(t.value);save();render();marketDialog();return;}
 else if(id==='talk-room')state=E.configureLife(state,'talk',t.value);else if(id==='meetup-venue')state=E.configureLife(state,'meetup',{...state.lifestyle.meetup,venue:t.value});
 else if(id==='training-style')state=E.setTraining(state,t.value);else if(id==='training-school')state=E.setTraining(state,state.training.style,t.value||null);
 else if(id==='school-type')schoolType=t.value;else if(id==='school-region')schoolRegion=t.value;
 else if(id==='import-save'){const file=t.files?.[0];if(!file)return;storageBusy=true;
 const showImportError=message=>{const feedback=$('import-feedback');if(feedback){feedback.textContent=message;feedback.hidden=false;}else toast(message);};
 (async()=>{let previous;
  try{const candidate=prepareSave(JSON.parse(await file.text()));previous={state,plan,slots};({state,plan,slots}=candidate);render();
   if(!await save())throw new Error('save failed');toast('セーブを読み込みました。');
  }catch(error){if(previous){({state,plan,slots}=previous);render();}showImportError(saveStatus==='conflict'?'別の画面で更新されています。現在の記録はそのままです。':'読み込めませんでした。現在の記録はそのままです。');}
  finally{storageBusy=false;t.value='';}
 })();return;}else return;
 save();render();}catch(err){toast(err.message);}}
let searchTimer;
function liveSearch(e){if(storageBusy)return;const id=e.target.id;if(!['shop-query','school-query','venue-query'].includes(id)||e.isComposing)return;const value=e.target.value,focused=document.activeElement===e.target,start=e.target.selectionStart,end=e.target.selectionEnd;if(id==='shop-query'){shopQuery=value;shopLimit=36;pages.shop=0;}else if(id==='school-query'){schoolQuery=value;pages.schools=0;}else{venueQuery=value;venueLimit=12;pages.venues=0;}clearTimeout(searchTimer);render();if(focused){const input=$(id);input?.focus({preventScroll:true});if(start!==null&&end!==null)input?.setSelectionRange?.(start,end);}}
root.addEventListener('input',liveSearch);
root.addEventListener('click',action);root.addEventListener('change',change);
window.addEventListener('beforeunload',e=>{if(state&&saveStatus!=='saved'){e.preventDefault();e.returnValue='';}});
boot();
